import React, { useEffect, useState } from 'react';
import { getHistory, getRecommendations } from '../services/api';

const categoryIcons = { sleep: '😴', stress: '🧘', activity: '🏃', wellness: '💚' };

export default function Recommendations() {
  const [categories, setCategories] = useState(null);
  const [risk, setRisk] = useState('');

  useEffect(() => {
    getHistory().then((r) => {
      const latest = r.data.history?.[0];
      const level = latest?.prediction || 'Moderate Risk';
      setRisk(level);
      getRecommendations(level).then((res) => {
        if (res.data.categories) setCategories(res.data.categories);
      });
    });
  }, []);

  if (!categories) return <div><h2>Recommendations</h2><p>Loading...</p></div>;

  return (
    <div>
      <h2 className="mb-2">Personalized Recommendations</h2>
      <p className="text-muted mb-4">Based on your risk level: <strong>{risk}</strong></p>
      <div className="row g-3">
        {Object.entries(categories).map(([cat, items]) => (
          <div className="col-md-6" key={cat}>
            <div className="card card-mw p-3 h-100">
              <h5>{categoryIcons[cat] || '💡'} {cat.charAt(0).toUpperCase() + cat.slice(1)}</h5>
              <ul className="mb-0">
                {items.map((t, i) => <li key={i}>{t}</li>)}
              </ul>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
